head.script:
// 화면 리사이징

scwin.vUsrTpCd = js_usr_tp_cd; // '1'관리자, '4'현업
scwin.gLdMktTp = js_market;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
        scwin.resizeToWin();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30006.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30006.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_SCHEDULE_OnLoadCompleted
 * @description dts_SCHEDULE 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_SCHEDULE_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.panelMsg(panel_msg, "총 : " + $c.stf.FormatNumberEx(rowcount) + " 건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30006.dts_SCHEDULE_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_SCHEDULE_OnLoadError
 * @description dts_SCHEDULE 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_SCHEDULE_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_SCHEDULE);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30006.dts_SCHEDULE_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Save_onclick = function() {
    try {
        scwin.save();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30006.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30006.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        // alert("저장 성공");
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30006.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF30006.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "공시일정관리항목", type: 8}); // 16
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30006.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        if (colid === "X_PATH_NM") {
            if (dts_SCHEDULE.getCellData(row, "DISCLS_SCHDL_ADM_BAS_TP_CD") === '01') {
                await scwin.openForm(dts_SCHEDULE.getCellData(row, "REAL_FORM_CD"), dts_SCHEDULE.getCellData(row, "REAL_FORM_VER"), cmb_DEP_CD.getValue(), dts_SCHEDULE.getCellData(row, "X_PATH"), dts_SCHEDULE.getCellData(row, "SCHDL_ADM_ITM_TP_NM"));
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30006.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name txb_SCHDL_ADM_ITM_TP_NM_onclick
 * @description txb_SCHDL_ADM_ITM_TP_NM 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_SCHDL_ADM_ITM_TP_NM_onclick = async function() {
    try {
        if (event.keyCode === 13) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30006.txb_SCHDL_ADM_ITM_TP_NM_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        const options = {
            id: "ULDSTF39203",
            title: "공시일정계산식 등록",
            type: "browserPopup",
            width: "1300px",
            height: "850px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/dsclmgt/ULDSTF39203.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30006.btn_New_onclick" });
    }
};

/**
 * @method
 * @name btn_RPT_onclick
 * @description btn_RPT 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_RPT_onclick = async function() {
    try {
        const options = {
            id: "ULDSTF30003",
            title: "보고서 선택",
            type: "browserPopup",
            width: "350px",
            height: "570px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/dsclmgt/ULDSTF30003.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30006.btn_RPT_onclick" });
    }
};

/**
 * @method
 * @name txb_FORM_CD_onblur
 * @description txb_FORM_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_FORM_CD_onblur = function() {
    try {
        if (txb_FORM_CD.getValue() === "") {
            txb_FORM_KOR_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30006.txb_FORM_CD_onblur" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description 평가부문
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    // 평가부문
    const sbmOptions = {
        id : "sbm_dts_schelAdmBas",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_schelAdmBas=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (scwin.vUsrTpCd !== null && scwin.vUsrTpCd === '1') {
        // 관리자
        btn_New.show("");
        btn_Save.show("");
        rdo_MKT_ID.setValue("1");
    } else {
        // 현업
        if (scwin.gLdMktTp === '' || scwin.gLdMktTp === '9') {
            rdo_MKT_ID.setValue("1");
        } else {
            rdo_MKT_ID.setValue(scwin.gLdMktTp); // 시장구분
            rdo_MKT_ID.setDisabled(true);
        }
        btn_New.hide();
        btn_Save.hide();
        label_5.hide();
        cmb_DEP_CD.hide(); // 팀구분
        label_3.hide();
        cmb_USE_YN.hide(); // 사용여부
        label_4.hide();
        cmb_DELETE.hide(); // 서식폐지여부
        label_1.hide();
        cmb_ADM_BAS_TP_CD.hide(); // 서식폐지여부

        $c.cm.setColumnProp(grd_Grid, "AUTO_CALC_YN", "show", false); // 자동계산
        $c.cm.setColumnProp(grd_Grid, "X_PATH", "show", false);
        $c.cm.setColumnProp(grd_Grid, "APPL_REQ_DD", "show", false);
        $c.cm.setColumnProp(grd_Grid, "DISCLS_SCHDL_REQSTR_NM", "show", false);
        $c.cm.setColumnProp(grd_Grid, "REQ_CONTN", "show", false);
        $c.cm.setColumnProp(grd_Grid, "USE_YN", "show", false);
        $c.cm.setColumnProp(grd_Grid, "DISCLS_SCHDL_ADM_CONTN", "show", false);
        if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '3') {
            $c.cm.setColumnProp(grd_Grid, "DISCLS_SCHDL_GRD_CD", "show", true); // 등급
            $c.cm.setColumnProp(grd_Grid, "SMS_TRNSM_YN", "show", false); // SMS
            label_9.hide();
            cmb_SMS_TRNSM_YN.hide();
        } else if (scwin.gLdMktTp === '2' || scwin.gLdMktTp === '6') {
            $c.cm.setColumnProp(grd_Grid, "DISCLS_SCHDL_GRD_CD", "show", false); // 등급
            $c.cm.setColumnProp(grd_Grid, "SMS_TRNSM_YN", "show", true); // SMS

        }
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const vMKT_ID = rdo_MKT_ID.getValue();
    const vFORM_CD = txb_FORM_CD.getValue();
    let vUSE_YN = cmb_USE_YN.getValue();
    let vDELETE = cmb_DELETE.getValue(); // N : 미폐지, D : 폐지
    const vADM_BAS_TP_CD = cmb_ADM_BAS_TP_CD.getValue();
    let vDepCD = cmb_DEP_CD.getValue();
    let vDepCD = txb_FORM_KOR_NM.getValue(); // 서식명, 일정내용

    if (scwin.vUsrTpCd !== null && scwin.vUsrTpCd === '4') {
        // 현업사용자
        vUSE_YN = "Y";
        vDELETE = "N";
        vDepCD = js_team;
        if (vDepCD !== '' && vDepCD !== '13') {
            vDepCD = '0';
        }
    }
    url += "&MKT_ID=" + vMKT_ID;
    url += "&FORM_CD=" + vFORM_CD;
    url += "&USE_YN=" + vUSE_YN;
    url += "&DELETE=" + vDELETE;
    url += "&ADM_BAS_TP_CD=" + vADM_BAS_TP_CD;
    url += "&DEP_CD=" + vDepCD;
    url += "&SCHDL_ADM_ITM_TP_NM=" + txb_SCHDL_ADM_ITM_TP_NM.getValue();
    url += "&SUBMIT_SYS_USE_YN=" + cmb_SUBMIT_SYS_USE_YN.getValue();
    url += "&SMS_TRNSM_YN=" + cmb_SMS_TRNSM_YN.getValue();
    url += "&FORM_KOR_NM=" + txb_FORM_KOR_NM.getValue();
    url += "&SCREN_ID=" + 'ULDSTF30006.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    $c.stf.panelMsg(panel_msg, "로딩중....기다려주세요.");
    const sbmOptions = {
        id : "sbm_dts_SCHEDULE",
        action : "/DisclosureSchedule.do",
        ref : "",
        target : "dts_SCHEDULE=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name save
 * @description save 처리
 * @returns {void}
 * @hidden N
 */
scwin.save = function() {
    const res = window.confirm("저장 하시겠습니까?");
    if (res) {
        let url = "/DisclosureSchedule.do?method=saveScheduleAdmItems&SCREN_ID=" + 'ULDSTF30006.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_SCHEDULE)";
        trs_Save.Post();
    }
};

/**
 * @method
 * @name disclsClose
 * @description discls Close 처리
 * @returns {void}
 * @hidden N
 */
scwin.disclsClose = function() {
    dts_SCHEDULE.setBroadcast(false);
    for (let i = 1; i <= dts_SCHEDULE.getRowCount(); i++) {
        dts_SCHEDULE.setCellData(i, "REMK", dts_SCHEDULE.getCellData(i, "REMK") + "(서식폐지)");
    }
    dts_SCHEDULE.setBroadcast(true, true);
};

/**
 * @method
 * @name openForm
 * @description 서식별로 모든항목들에 대해서 보여주려 했으나 팝업호출시 문자열이 길어 호출시 에러발생. 건별로 양식보기에서 보여준다.
 * @param {*} form_cd form_cd
 * @param {*} form_ver form_ver
 * @param {*} dep_cd dep_cd
 * @param {*} x_path x_path
 * @param {*} schdl_adm_itm_tp_nm schdl_adm_itm_tp_nm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openForm = async function(form_cd, form_ver, dep_cd, x_path, schdl_adm_itm_tp_nm) {
    // 서식별로 모든항목들에 대해서 보여주려 했으나 팝업호출시 문자열이 길어 호출시 에러발생. 건별로 양식보기에서 보여준다.
    // var form_x_path = getFormXPath(form_cd,x_path);
    const form_x_path = scwin.StringToHex4(schdl_adm_itm_tp_nm) + ":" + x_path;
    let url;
    if (js_svrGubun.indexOf("test") > -1) {
        url = g_test_manager_url + "/filing/findForm.do?method=scheduleFormView";
    } else if (js_svrGubun === 'dev') {
        url = g_dev_manager_url + "/filing/findForm.do?method=scheduleFormView";
    } else {
        url = g_real_manager_url + "/filing/findForm.do?method=scheduleFormView";
    }
    url += "&formCd=" + form_cd;
    url += "&formVer=" + form_ver;
    url += "&form_x_path=" + form_x_path;
    const winTitle = url;
    await $c.frame.CreateDialogFrame("formPop", url, winTitle, 10, 10, 800, 700, "window");
};

/**
 * @method
 * @name StringToHex4
 * @description String To Hex4 처리
 * @param {*} OriginalString OriginalString
 * @returns {void}
 * @hidden N
 */
scwin.StringToHex4 = function(OriginalString) {
    let ReturnString = "";
    for (let i = 0; i < OriginalString.length; i++) {
        const tmp = "0000" + (parseInt(OriginalString.charCodeAt(i)).toString(16));
        const tmp2 = tmp.substring(tmp.length - 4);
        ReturnString += tmp2;
    }
    return ReturnString.toUpperCase();
};

/**
 * @method
 * @name getFormXPath
 * @description get Form XPath 처리
 * @param {*} form_cd form_cd
 * @param {*} x_path x_path
 * @returns {void}
 * @hidden N
 */
scwin.getFormXPath = function(form_cd, x_path) {
    let str = "";
    for (let i = 0; i < dts_SCHEDULE.getRowCount(); i++) {
        if (form_cd === dts_SCHEDULE.getCellData(i, "FORM_CD")) {
            if (i === 0) {
                str += dts_SCHEDULE.getCellData(i, "SCHDL_ADM_ITM_TP_NM");
                str += ":" + dts_SCHEDULE.getCellData(i, "X_PATH");
            } else {
                str += "," + dts_SCHEDULE.getCellData(i, "SCHDL_ADM_ITM_TP_NM");
                str += ":" + dts_SCHEDULE.getCellData(i, "X_PATH");
            }
        }
    }
    return str;
};

/**
 * @method
 * @name resizeToWin
 * @description resize To Win 처리
 * @returns {void}
 * @hidden N
 */
scwin.resizeToWin = function() {
    frame.Width = 1300;
    frame.Height = 800;
};

/**
 * @method
 * @name grd_Grid_CanColumnPosChange
 * @description grd Grid Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    return true;
};
